/** Solar Icons (solar-icons.dev, saoudi-h/solar-icons): Bold ve Linear stilleri. */
class Solar(val bold: ImageVector, val linear: ImageVector)

private fun bold(name: String, vararg d: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).apply {
        d.forEach { addPath(PathParser().parsePathString(it).toNodes(), pathFillType = PathFillType.EvenOdd, fill = SolidColor(Color.Black)) }
    }.build()

private fun lin(name: String, vararg d: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).apply {
        d.forEach { addPath(PathParser().parsePathString(it).toNodes(), fill = null, stroke = SolidColor(Color.Black), strokeLineWidth = 1.5f, strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round) }
    }.build()

